def resolve(path, cwd, links):
    if cwd[-1] == '/' and cwd != '/':
        return None

    current = cwd if path[0] != '/' else '/'

    if path[0] == '/':
        components = path[1:].split('/')
    else:
        components = path.split('/')

    link_count = 0

    i = 0
    while i < len(components):
        comp = components[i]

        if comp == '' or comp == '.':
            i += 1
            continue

        if comp == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        if current == '/':
            next_path = '/' + comp
        else:
            next_path = current + '/' + comp

        if next_path in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[next_path]

            if target[0] == '/':
                current = '/'
                target_components = target[1:].split('/')
            else:
                target_components = target.split('/')

            components = target_components + components[i+1:]
            i = 0
        else:
            current = next_path
            i += 1

    if current == '/':
        return '/'
    else:
        return current

